-- 0027_aztec_character_canonical_designs.sql
-- Generation-grade Canonical Design enrichments for 12 Aztec launch characters.
PRAGMA foreign_keys = ON;

UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"majestic feathered serpent with long flowing body and wind-shell ornament","appearance":{"face":["serpent head with elegant feather crest"],"body":["long limbless serpent body with coherent feather transitions"]},"costumeLanguage":["no humanoid clothing; quetzal feathers, shell and carved-stone motifs only"],"paletteCues":["quetzal green","turquoise","white"],"temperament":["wise","civilizing","windborne"],"mythologicalFacts":["major feathered-serpent deity associated with wind, knowledge and culture"],"originalDesignChoices":["Keep Aztec/Mexica visual identity distinct from Maya Kukulkan through turquoise, shell and Central Mexican iconography."],"avoid":["East Asian dragon anatomy","European dragon wings","specific modern franchise likeness"],"canonicalPrompt":"Depict Quetzalcoatl as an original MythCanvas Aztec feathered-serpent deity. Preserve the limbless serpent body, quetzal feathers, wind and shell motifs. Use turquoise, carved-stone and Central Mexican sacred ornament while avoiding generic dragon anatomy."}') WHERE id='character-quetzalcoatl';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"powerful adult warrior-sun deity with hummingbird headdress and serpent-shaped weapon forming a sharp diagonal","appearance":{"face":["adult warrior face with fierce focused gaze"],"body":["athletic powerful adult build"]},"costumeLanguage":["Mexica warrior-divine regalia with hummingbird feathers, turquoise mosaic and restrained shield ornament"],"paletteCues":["turquoise","solar gold","deep blue"],"temperament":["martial","radiant","unyielding"],"mythologicalFacts":["patron deity of the Mexica associated with sun and war"],"originalDesignChoices":["Keep Xiuhcoatl and hummingbird symbolism primary; avoid generic Mesoamerican warrior mashups."],"avoid":["generic tribal warrior","specific modern franchise likeness"],"canonicalPrompt":"Depict Huitzilopochtli as an original MythCanvas Mexica solar-war deity. Preserve hummingbird symbolism, the Xiuhcoatl serpent weapon, shield and solar force. Use turquoise-and-feather warrior regalia with a fierce adult divine presence grounded in Mexica iconography."}') WHERE id='character-huitzilopochtli';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"mature adult god with smoking obsidian mirror, jaguar pelt and asymmetrical night silhouette","appearance":{"face":["mature adult face with severe penetrating gaze and dark facial markings"],"body":["strong lean adult build"]},"costumeLanguage":["elite Mexica divine regalia with obsidian mirror, jaguar skin and turquoise details"],"paletteCues":["obsidian black","jaguar gold","smoke grey"],"temperament":["ominous","sovereign","unpredictable"],"mythologicalFacts":["major deity associated with night, rulership, fate and the smoking mirror"],"originalDesignChoices":["Use mirror and jaguar as primary identifiers; keep him divine, not a generic dark sorcerer."],"avoid":["generic necromancer","specific modern franchise likeness"],"canonicalPrompt":"Depict Tezcatlipoca as an original MythCanvas Aztec deity of night and fate. Preserve the smoking obsidian mirror, jaguar symbolism and elite divine regalia. Use a mature, severe adult presence with controlled smoke and obsidian effects rather than generic dark-fantasy sorcery."}') WHERE id='character-tezcatlipoca';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"adult rain deity with iconic goggle-like eyes, fangs and water-serpent storm framing","appearance":{"face":["iconographic circular eye forms and downward fangs with divine rather than monstrous expression"],"body":["strong adult humanoid proportions"]},"costumeLanguage":["Mexica rain ceremonial regalia with blue-green paper, jade, shell and water motifs"],"paletteCues":["rain blue","jade","cloud white"],"temperament":["fertile","formidable","elemental"],"mythologicalFacts":["major rain and water deity central to agriculture"],"originalDesignChoices":["Keep facial iconography culturally specific and avoid confusing him with Maya Chaac."],"avoid":["generic demon mask","Maya Chaac conflation","specific modern franchise likeness"],"canonicalPrompt":"Depict Tlaloc as an original MythCanvas Aztec rain deity. Preserve the circular goggle-like eye forms, fangs, rain and water-serpent symbolism. Use Mexica rain regalia with jade and blue-green materials, keeping the face iconic and divine rather than monstrous."}') WHERE id='character-tlaloc';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"monumental adult earth mother with serpent skirt, massive necklace and broad sculptural stance","appearance":{"face":["symbolic serpent-formed head or severe mature maternal face depending canonical composition"],"body":["massive mature adult earth-mother proportions"]},"costumeLanguage":["serpent skirt, clawed earth motifs and heavy ritual necklace based on Mexica sculptural language"],"paletteCues":["basalt black","earth red","serpent green"],"temperament":["maternal","terrible","primordial"],"mythologicalFacts":["earth mother deity associated with life, death and the birth of Huitzilopochtli"],"originalDesignChoices":["Honor monumental stone-sculpture language without gratuitous gore."],"avoid":["gore fetish","generic snake demon","specific modern franchise likeness"],"canonicalPrompt":"Depict Coatlicue as an original MythCanvas Aztec earth mother grounded in monumental Mexica sculpture. Preserve the serpent skirt, massive ritual necklace and life-death earth symbolism. Keep the figure awe-inspiring and primordial without gore or generic snake-demon styling."}') WHERE id='character-coatlicue';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"adult agricultural-renewal deity with vertical maize rhythm and ceremonial skin-layer symbolism","appearance":{"face":["adult ritual face with calm severe gaze"],"body":["lean adult humanoid build"]},"costumeLanguage":["Mexica spring and maize regalia with gold-yellow outer ritual layer handled symbolically"],"paletteCues":["maize gold","spring green","red ochre"],"temperament":["renewing","austere","agricultural"],"mythologicalFacts":["deity associated with agricultural renewal and springtime rites"],"originalDesignChoices":["Represent flayed-skin symbolism abstractly and ceremonially, never as graphic gore."],"avoid":["graphic flaying","body horror","specific modern franchise likeness"],"canonicalPrompt":"Depict Xipe Totec as an original MythCanvas Aztec deity of agricultural renewal. Preserve maize, spring and ceremonial renewal symbolism. Render the traditional skin-layer motif abstractly through ritual garment layering and gold-earth color, with no graphic gore or body-horror treatment."}') WHERE id='character-xipe-totec';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"skeletal adult underworld king with tall headdress and rigid frontal ritual stance","appearance":{"face":["skull face rendered as sacred iconography rather than realistic corpse detail"],"body":["lean skeletal adult humanoid proportions"]},"costumeLanguage":["Mexica underworld regalia with owl, bone and dark-paper ornament"],"paletteCues":["bone white","obsidian","night red"],"temperament":["grim","sovereign","ritual"],"mythologicalFacts":["ruler of Mictlan, the land of the dead"],"originalDesignChoices":["Keep the skull form archaeological/iconographic and avoid European Grim Reaper imagery."],"avoid":["gore","black hooded grim reaper","specific modern franchise likeness"],"canonicalPrompt":"Depict Mictlantecuhtli as an original MythCanvas Aztec underworld king. Preserve the skull visage, owl and Mictlan ritual symbolism. Use Mexica funerary regalia and a rigid sovereign posture, avoiding gore, zombies or a European Grim Reaper silhouette."}') WHERE id='character-mictlantecuhtli';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"clearly adult underworld queen with skull symbolism, long ceremonial skirt and night-flower framing","appearance":{"face":["clearly adult skeletal or death-painted face rendered iconographically"],"body":["graceful adult proportions"]},"costumeLanguage":["Mexica funerary ceremonial dress with bone, paper and night-flower motifs"],"paletteCues":["bone white","night black","marigold accent"],"temperament":["solemn","sovereign","watchful"],"mythologicalFacts":["female ruler associated with Mictlan alongside Mictlantecuhtli"],"originalDesignChoices":["Keep her distinct from modern Day-of-the-Dead fashion imagery."],"avoid":["modern Catrina fashion","gore","specific modern franchise likeness"],"canonicalPrompt":"Depict Mictecacihuatl as an original MythCanvas adult Aztec underworld queen. Preserve skeletal death symbolism, night and funerary ritual motifs. Use Mexica ceremonial dress with a solemn sovereign presence, avoiding modern Catrina fashion or gore."}') WHERE id='character-mictecacihuatl';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"radiant adult solar deity centered in a circular sun-disk composition with eagle accents","appearance":{"face":["adult stern solar face with direct frontal gaze"],"body":["strong adult humanoid proportions"]},"costumeLanguage":["Mexica solar regalia with eagle, turquoise and sun-ray ornament"],"paletteCues":["solar gold","turquoise","fire red"],"temperament":["radiant","demanding","sovereign"],"mythologicalFacts":["solar deity associated with the Fifth Sun"],"originalDesignChoices":["Use sun-stone geometry as inspiration without turning him into a literal stone calendar."],"avoid":["generic fire god","specific modern franchise likeness"],"canonicalPrompt":"Depict Tonatiuh as an original MythCanvas Aztec solar deity of the Fifth Sun. Preserve the frontal sun-disk, eagle and radiant fire motifs. Use Mexica solar regalia with turquoise and gold, maintaining a stern adult divine presence rather than generic fire-god styling."}') WHERE id='character-tonatiuh';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"clearly adult lunar goddess with circular cheek-bell motifs and a strong disk-like composition","appearance":{"face":["clearly adult noble face with proud defiant gaze"],"body":["athletic graceful adult build"]},"costumeLanguage":["Mexica warrior-princess ceremonial regalia with bells, feathers and lunar ornament"],"paletteCues":["moon silver","turquoise","night blue"],"temperament":["proud","defiant","tragic"],"mythologicalFacts":["sister and opponent of Huitzilopochtli in the Coatepec birth myth"],"originalDesignChoices":["Use moon-disk and bell motifs; avoid dismemberment imagery except when explicitly scene-driven."],"avoid":["gore","generic moon princess","specific modern franchise likeness"],"canonicalPrompt":"Depict Coyolxauhqui as an original MythCanvas adult Aztec lunar goddess. Preserve cheek-bell, moon-disk and star-warrior symbolism. Use Mexica ceremonial regalia with a proud, defiant adult presence, avoiding gore or generic fantasy moon-princess styling."}') WHERE id='character-coyolxauhqui';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"mature adult fire lord with turquoise crown and central brazier creating a compact radiant silhouette","appearance":{"face":["mature adult face with calm ancient authority"],"body":["sturdy mature adult proportions"]},"costumeLanguage":["Mexica fire ceremonial regalia with turquoise mosaic, brazier and ember motifs"],"paletteCues":["turquoise","ember orange","charcoal"],"temperament":["ancient","steady","renewing"],"mythologicalFacts":["deity associated with fire, hearth and year-cycle renewal"],"originalDesignChoices":["Treat turquoise and brazier as primary identifiers; avoid generic flame armor."],"avoid":["generic fire armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Xiuhtecuhtli as an original MythCanvas Aztec fire-and-time deity. Preserve the turquoise crown, sacred brazier and year-renewal symbolism. Use Mexica ceremonial regalia with a mature, steady adult presence and restrained ember effects."}') WHERE id='character-xiuhtecuhtli';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"youthful-adult flower prince with dancing posture, blossoms and butterfly motifs forming an open festive silhouette","appearance":{"face":["clearly adult youthful face with joyful artistic gaze"],"body":["lean graceful adult build"]},"costumeLanguage":["rich Mexica festival garments with flower, butterfly and music ornament"],"paletteCues":["flower red","maize gold","turquoise"],"temperament":["joyful","artistic","sensuous"],"mythologicalFacts":["deity associated with flowers, art, music, dance and pleasure"],"originalDesignChoices":["Keep sensuality adult and festival-based rather than nightclub or modern fashion styling."],"avoid":["modern party costume","youth-coded sexualization","specific modern franchise likeness"],"canonicalPrompt":"Depict Xochipilli as an original MythCanvas youthful-adult Aztec god of flowers and arts. Preserve blossoms, butterflies, music and dance motifs. Use rich Mexica festival garments with a joyful, artistic and clearly adult presence."}') WHERE id='character-xochipilli';
